{"filename": "test_merge_inventory.py", "content": "import os
import importlib.util
import copy

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
merge_inventory = target.merge_inventory


def test_basic_merge_non_overlapping():
    """Merging two dicts with no common SKUs produces a union."""
    base = {"apple": 3, "banana": 5}
    incoming = {"cherry": 2, "date": 7}
    result = merge_inventory(base, incoming)
    assert result == {"apple": 3, "banana": 5, "cherry": 2, "date": 7}


def test_basic_merge_overlapping():
    """Matching SKUs should have their counts added together."""
    base = {"apple": 3, "banana": 5}
    incoming = {"apple": 2, "cherry": 1}
    result = merge_inventory(base, incoming)
    assert result == {"apple": 5, "banana": 5, "cherry": 1}


def test_base_not_mutated():
    """The base dictionary should not be mutated."""
    base = {"apple": 3}
    base_copy = copy.deepcopy(base)
    incoming = {"apple": 2, "banana": 1}
    merge_inventory(base, incoming)
    assert base == base_copy


def test_incoming_not_mutated():
    """The incoming dictionary should not be mutated."""
    incoming = {"apple": 2, "banana": 1}
    incoming_copy = copy.deepcopy(incoming)
    base = {"apple": 3}
    merge_inventory(base, incoming)
    assert incoming == incoming_copy


def test_returns_new_dict():
    """The result should be a new dict, not either input."""
    base = {"a": 1}
    incoming = {"b": 2}
    result = merge_inventory(base, incoming)
    assert result is not base
    assert result is not incoming


def test_both_empty():
    """Merging two empty dicts gives an empty dict."""
    result = merge_inventory({}, {})
    assert result == {}


def test_base_empty():
    """Merging empty base with incoming gives incoming's contents."""
    base = {}
    incoming = {"x": 10, "y": 20}
    result = merge_inventory(base, incoming)
    assert result == {"x": 10, "y": 20}


def test_incoming_empty():
    """Merging base with empty incoming gives base's contents."""
    base = {"x": 10, "y": 20}
    incoming = {}
    result = merge_inventory(base, incoming)
    assert result == {"x": 10, "y": 20}


def test_zero_counts():
    """Zero counts are valid (non-negative)."""
    base = {"a": 0}
    incoming = {"a": 5}
    result = merge_inventory(base, incoming)
    assert result == {"a": 5}


def test_non_dict_base_raises_type_error():
    """Passing a non-dict as base should raise TypeError."""
    try:
        merge_inventory([1, 2, 3], {"a": 1})
        assert False, "Expected TypeError"
    except TypeError:
        pass


def test_non_dict_incoming_raises_type_error():
    """Passing a non-dict as incoming should raise TypeError."""
    try:
        merge_inventory({"a": 1}, "not a dict")
        assert False, "Expected TypeError"
    except TypeError:
        pass


def test_negative_count_raises_value_error():
    """Negative counts should raise ValueError."""
    try:
        merge_inventory({"a": -1}, {"b": 1})
        assert False, "Expected ValueError"
    except ValueError:
        pass


def test_negative_incoming_count_raises_value_error():
    """Negative counts in incoming should raise ValueError."""
    try:
        merge_inventory({"a": 1}, {"b": -5})
        assert False, "Expected ValueError"
    except ValueError:
        pass


def test_non_int_count_raises_type_error():
    """Non-integer counts should raise TypeError."""
    try:
        merge_inventory({"a": 1.5}, {"b": 1})
        assert False, "Expected TypeError"
    except TypeError:
        pass


def test_multiple_overlapping_skus():
    """Multiple overlapping SKUs all get summed correctly."""
    base = {"a": 1, "b": 2, "c": 3}
    incoming = {"a": 10, "b": 20, "c": 30, "d": 40}
    result = merge_inventory(base, incoming)
    assert result == {"a": 11, "b": 22, "c": 33, "d": 40}
"}

